(() => {
  const segments = [...new Set(
    zt.collections
      .flatMap(c => c.path)
      .map(s => s.replace(/\+/, "").trim())
      .filter(Boolean)
  )];

  return segments
    .filter(s => /🗺️/.test(s))
    .map(s => `[[${s.replace(/🗺️/g, "").trim()}]]`)
    .filter(s => s !== "[[]]");
})()

