(() => {
  const url = zt.url?.trim();
  if (!url) return [];

  let host = "";
  try {
    host = new URL(url).hostname
      .replace(/^www\./, "")
      .toLowerCase();
  } catch {}

  let label;

  if (
    host === "youtube.com" ||
    host.endsWith(".youtube.com") ||
    host === "youtu.be"
  ) {
    label = "YouTube";
  } else {
    label =
      zt.publicationTitle?.trim() ||
      zt.publisher?.trim() ||
      zt.libraryCatalog?.trim() ||
      host ||
      "Source";
  }

  label = label.replace(/[\[\]]/g, "");

  return [`[${label}](<${url}>)`];
})()

(() => {
  const names = zt.tags.map(t => t.name);

  if (names.some(t => /inbox|📥/i.test(t))) return "📥";
  if (names.some(t => /todo|🟥/i.test(t))) return "🟥";
  if (names.some(t => /wip|🟦/i.test(t))) return "🟦";
  if (names.some(t => /atom|⚛/i.test(t))) return "⚛";
  if (names.some(t => /done|🟩/i.test(t))) return "🟩";

  return undefined;
})()

(() => {
  const d = new Date();
  const pad = n => String(n).padStart(2, "0");

  const offset = -d.getTimezoneOffset();
  const sign = offset >= 0 ? "+" : "-";
  const offsetHours = pad(Math.floor(Math.abs(offset) / 60));
  const offsetMinutes = pad(Math.abs(offset) % 60);

  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}${sign}${offsetHours}:${offsetMinutes}`;
})()
